INSERT INTO `Course` (`title`, `slug`, `description`, `thumbnail`, `published`, `createdAt`, `updatedAt`, `id`, `categoryId`, `avgRating`, `discount`, `duration`, `hasCertificate`, `hasExam`, `level`, `price`, `studentNumber`, `careerFields`, `learningOutcomes`, `overview`, `conductingType`, `estimatedSalary`, `expectedIncome`, `growthPercentage`, `hiringSectors`, `instructorId`) VALUES
	('Leading High-Performance Teams', 'leading-high-performance-teams', 'Strategies for building elite group dynamics.', 'https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&q=80&w=800', true, '2026-04-29 23:22:35.733', '1969-12-31 22:00:00', '3167514a-8148-4789-a95b-15ee856f2772', '3e4ce107-02f9-4c65-b0f1-d49aa2939dac', 3.4, 20.00, '120 Hours', true, true, 'ADVANCED', 100.00, 40, '["Team Lead","Department Head","HR Business Partner","Scrum Master"]', '["Build frameworks for psychological safety","Master conflict resolution techniques","Design high-impact feedback loops","Optimize team workflows using Agile leadership"]', '["Management is about tasks, but leadership is about people. This course explores the mechanics of group dynamics and the psychological safety required to foster innovation in diverse environments.","You will learn how to transition from a \\"command and control\\" style to a servant-leadership model. We focus on building trust-based cultures that consistently over-deliver on KPIs while maintaining high employee retention."]', 'OnSite', '$8k/month', '$90k - $160k', 12, '["Tech Operations","HR Management","Project Management"]', 'cmpctkz770000rhpddom4rnp7'),
	('Executive Decision Making', 'executive-decision-making', 'Master the art of choosing under pressure.', 'https://images.unsplash.com/photo-1507679799987-c73779587ccf?auto=format&fit=crop&q=80&w=800', true, '2026-04-29 23:22:35.733', '1969-12-31 22:00:00', '41e9c0f6-6b32-401a-bdf0-9d404343157c', '3e4ce107-02f9-4c65-b0f1-d49aa2939dac', 3, 45.00, '110 Hours', true, false, 'BEGINNER', 120.00, 20, '["Operations Director","CEO/Founder","Strategic Consultant","Senior Project Manager"]', '["Master the OODA Loop for rapid situational analysis","Identify and neutralize cognitive biases in boardrooms","Apply Game Theory to predict competitor moves","Construct data-driven decision trees for risk management"]', '["Effective leadership in 2026 requires more than just intuition; it demands a systematic approach to processing complex information and mitigating inherent biases. This course provides an intensive deep-dive into the cognitive science behind high-stakes decision-making.","Effective leadership in 2026 requires more than just intuition; it demands a systematic approach to processing complex information and mitigating inherent biases. This course provides an intensive deep-dive into the cognitive science behind high-stakes decision-making."]', 'Hybrid', '$12k/month', '$150k - $250k', 18.5, '["Venture Capital","Corporate Strategy","Public Policy"]', 'cmpctkz770000rhpddom4rnp7'),
	('Emotional Intelligence for Leaders', 'emotional-intelligence-leaders', 'Developing self-awareness and empathy.', 'https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?auto=format&fit=crop&q=80&w=800', true, '2026-04-29 23:22:35.733', '1969-12-31 22:00:00', 'a3e7130c-e092-4f5f-82ed-ab2bbab34485', '3e4ce107-02f9-4c65-b0f1-d49aa2939dac', 3.6, 60.00, '91 Hours', true, true, 'INTERMEDIATE', 400.00, 98, '["Executive Coach","Public Relations Manager","Change Management Lead","Mid-level Manager"]', '["Develop advanced self-regulation techniques","Increase empathy and social awareness","Improve non-verbal communication skills","Learn to lead with high-impact emotional influence"]', '["Soft skills are the new hard skills. This course teaches leaders how to harness self-awareness and empathy to navigate the complexities of modern organizational life.","By developing your EQ, you will improve your ability to influence without authority and manage the stress of high-pressure environments. This is a foundational course for anyone moving from technical roles into management."]', 'Online', '$9k/month', '$100k - $180k', 22, '["Executive Coaching","Public Relations","Leadership Development"]', 'cmp8kn4u80001lcpdkabi1nhf'),
	('Strategic Change Management', 'strategic-change-management', 'How to lead organizations through transition.', 'https://plus.unsplash.com/premium_photo-1661414415246-3e502e2fb241?auto=format&fit=crop&w=800&q=80', true, '2026-04-29 23:22:35.733', '1969-12-31 22:00:00', 'd5d208c9-6b35-4185-8eb8-1d9d2301efbe', '3e4ce107-02f9-4c65-b0f1-d49aa2939dac', 3.4, 50.00, '420 Hours', true, true, 'INTERMEDIATE', 750.00, 59, '["Transformation Officer","Internal Consultant","Strategy Lead","Operations Manager"]', '["Apply Kotter’s 8-Step Process for Leading Change","Identify and manage stakeholder resistance","Create transparent internal communication strategies","Measure the ROI of transformation initiatives"]', '["In a rapidly evolving market, the only constant is change. This course prepares you to lead your organization through digital transformations, mergers, and shifts in market strategy.","We provide a blueprint for overcoming resistance to change and aligning stakeholders at every level. You will finish the course with a toolkit for managing the \\"human side\\" of organizational restructuring."]', 'Online', '$11k/month', '$130k - $210k', 15.2, '["Management Consulting","Global Logistics","Financial Services"]', 'cmp8kojvh0002lcpdktcx92y7'),
	('Advanced SEO Strategy', 'advanced-seo-strategy', 'Dominating search results in 2026.', 'https://images.unsplash.com/photo-1571721795195-a2ca2d3370a9?auto=format&fit=crop&q=80&w=800', true, '2026-04-29 23:31:27.516', '1969-12-31 22:00:00', 'e7d4e4c0-32e1-4e6e-9a73-fe59d2227ad6', 'fbd5e106-af72-4f88-b1f4-6710298e67ec', 3.6, 50.00, '70 Hours', true, false, 'ADVANCED', 90.00, 190, '["SEO Specialist","Content Architect","Search Engine Marketer","E-commerce Manager"]', '["Perform deep technical SEO audits","Build topical authority through content clusters","Optimize for Core Web Vitals and Page Experience","Implement advanced Schema markup for Rich Snippets"]', '["Stop chasing algorithms and start mastering the architecture of the web. This course goes beyond keywords to explore technical SEO, semantic search, and AI-driven content optimization.","We focus on \\"Core Web Vitals\\" and Topical Authority to ensure your platform dominates search results in 2026 and beyond."]', 'Online', '$6k/month', '$70k - $130k', 10.5, '["Content Marketing","Media Houses","E-commerce"]', 'cmp8kojvh0002lcpdktcx92y7'),
	('Growth Hacking Fundamentals', 'growth-hacking-fundamentals', 'Rapid experimentation across marketing channels.', 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&q=80&w=800', true, '2026-04-29 23:31:27.516', '1969-12-31 22:00:00', '810523d8-6cf8-4fbc-9af6-a27d2133f0d6', 'fbd5e106-af72-4f88-b1f4-6710298e67ec', 4, 60.00, '40 Hours', true, true, 'INTERMEDIATE', 129.00, 67, '["Growth Marketer","Product Manager","Startup Founder","Digital Strategist"]', '["Master the AARRR (Pirate) Metrics framework","Build and test viral growth loops","Perform high-velocity A/B testing","Optimize landing pages for massive conversions"]', '["Move beyond traditional advertising. This course teaches the \\"lean\\" approach to marketing, focusing on rapid experimentation across marketing channels and product development to identify the most efficient ways to grow a business.","You will learn how to turn your product into a marketing engine by engineering viral loops and optimizing the entire user journey from awareness to referral."]', 'Hybrid', '$7k/month', '$80k - $140k', 28.4, '["E-commerce","SaaS Startups","Digital Agencies"]', 'cmp8kn4u80001lcpdkabi1nhf'),
	('Scalable Operations for Startups', 'scalable-operations', 'Building systems that grow with your user base.', 'https://images.unsplash.com/photo-1504384308090-c894fdcc538d?auto=format&fit=crop&q=80&w=800', true, '2026-04-29 23:38:46.706', '1969-12-31 22:00:00', '6fb6a9dc-ac2a-486c-b2f9-5297814b60fd', 'a6053f70-4ab7-4ce9-b6ba-558a5bbe61f7', 3.4, 35.00, '25 Hours', true, false, 'BEGINNER', 150.00, 78, '["Chief Operating Officer (COO)","Operations Manager","Supply Chain Lead","Systems Analyst"]', '["Chief Operating Officer (COO)","Operations Manager","Supply Chain Lead","Systems Analyst"]', '["Moving from a 5-person team to a 100-person organization requires a different set of rules. This course teaches you how to build the systems and processes that allow a business to scale without breaking.","We focus on automation, supply chain management, and the implementation of standard operating procedures (SOPs) that ensure quality remains high as you grow."]', 'Online', '$10.5k/month', '$120k - $200k', 20.1, '["Operations Tech","Supply Chain","Logistics"]', 'cmp8kn4u80001lcpdkabi1nhf'),
	('Content Marketing Mastery', 'content-marketing-mastery', 'Building a brand through storytelling.', 'https://images.unsplash.com/photo-1499750310107-5fef28a66643?auto=format&fit=crop&q=80&w=800', true, '2026-04-29 23:31:27.516', '1969-12-31 22:00:00', 'd96d9df2-e34c-42f9-b800-a5f3dc244b16', 'fbd5e106-af72-4f88-b1f4-6710298e67ec', 3.6, 15.00, '90 Hours', true, true, 'INTERMEDIATE', 528.00, 34, '["Content Manager","Brand Strategist","Copywriter","Social Media Director"]', '["Develop a multi-channel content strategy","Master the art of brand storytelling","Create high-converting lead magnets","Measure content performance using data analytics"]', '["In the age of AI, high-quality storytelling is the ultimate differentiator. This course teaches you how to create a content engine that attracts, engages, and converts a loyal audience.","You will learn how to balance SEO requirements with human-centric storytelling to build a brand that resonates across blogs, social media, and newsletters."]', 'Hybrid', '$5.5k/month', '$65k - $120k', 14, '["Brand Management","Entertainment","Advertising"]', 'cmp8kojvh0002lcpdktcx92y7'),
	('Lean Startup Methodology', 'lean-startup-methodology', 'Validating ideas with minimal resources.', 'https://images.unsplash.com/photo-1559136555-9303baea8ebd?auto=format&fit=crop&q=80&w=800', true, '2026-04-29 23:38:46.706', '1969-12-31 22:00:00', '31b32592-7c01-46fc-b9de-274f1ab2298f', 'a6053f70-4ab7-4ce9-b6ba-558a5bbe61f7', 3.6, 30.00, '10 Hours', true, true, 'ADVANCED', 300.00, 34, '["Entrepreneur","Innovation Consultant","Venture Builder","Product Strategist"]', '["Build and test a Minimum Viable Product (MVP)","Perform effective customer discovery interviews","Define and validate your value proposition","Master the Pivot vs. Persevere decision process"]', '["Build something people actually want. This course is based on the principles of validated learning and rapid prototyping to minimize waste and maximize the chances of startup success.","You will learn how to build a Minimum Viable Product (MVP), test it with real users, and pivot based on evidence rather than ego."]', 'Online', '$10k/month', 'Equity + $100k+', 25, '["Venture Builders","Incubators","Product Design"]', 'cmpctkz770000rhpddom4rnp7'),
	('Business Model Innovation', 'business-model-innovation', 'Re-inventing how value is created and captured.', 'https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&q=80&w=800', true, '2026-04-29 23:38:46.706', '1969-12-31 22:00:00', '4ed14083-f09a-4f89-a57b-bb579b041eb2', 'a6053f70-4ab7-4ce9-b6ba-558a5bbe61f7', 3, 60.00, '512 Hours', true, true, 'ADVANCED', 600.00, 24, '["Business Developer","Strategic Planner","Corporate Innovator","Management Consultant"]', '["Master the Business Model Canvas","Identify opportunities for platform-based business","Design subscription and recurring revenue models","Analyze competitor business model vulnerabilities"]', '["Sometimes the best product is a better business model. This course explores how companies like Netflix and Uber disrupted industries not through technology alone, but through innovative value delivery.","Using the Business Model Canvas, you will learn how to identify new revenue streams and cost-saving structures in existing industries."]', 'Online', '$9.5k/month', '$110k - $190k', 16.5, '["Business Development","Corporate Innovation","Consulting"]', 'cmpctkz770000rhpddom4rnp7'),
	('Data-Driven Ad Campaigns', 'data-driven-ads', 'Maximizing ROI with analytics and AI.', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&q=80&w=800', true, '2026-04-29 23:31:27.516', '1969-12-31 22:00:00', '58a222cf-03ca-4fc2-91e9-9d92be85917a', 'fbd5e106-af72-4f88-b1f4-6710298e67ec', 3.4, 45.00, '89 Hours', true, true, 'ADVANCED', 120.00, 32, '["PPC Specialist","Performance Marketer","Ad Operations Manager","Digital Media Buyer"]', '["Set up advanced conversion tracking","Build lookalike and retargeting audiences","Optimize ad spend using attribution modeling","Write high-impact ad copy and creative briefs"]', '["Stop wasting budget on \\"guessing.\\" This course teaches you how to run precision-targeted campaigns on Meta, Google, and LinkedIn using advanced analytics and audience modeling.","We focus on the math of marketing—calculating Customer Acquisition Cost (CAC) and Lifetime Value (LTV) to ensure every dollar spent returns maximum profit."]', 'OnSite', '$8.5k/month', '$95k - $170k', 19.8, '["Performance Marketing","Retail Tech","FinTech"]', 'cmp8kn4u80001lcpdkabi1nhf'),
	('Venture Capital & Fundraising', 'vc-and-fundraising', 'How to pitch and secure startup capital.', 'https://images.unsplash.com/photo-1553729459-efe14ef6055d?auto=format&fit=crop&q=80&w=800', false, '2026-04-29 23:38:46.706', '1969-12-31 22:00:00', 'bd7f57ac-14aa-4c2e-8387-77f4bdd69564', 'a6053f70-4ab7-4ce9-b6ba-558a5bbe61f7', 3.2, 80.00, '910 Hours', true, false, 'INTERMEDIATE', 250.00, 12, '["Investment Associate","Chief Financial Officer (CFO)","Fundraising Consultant","Startup Founder"]', '["Understand Term Sheets and Equity Dilution","Create a compelling Investor Pitch Deck","Perform financial modeling and valuation","Navigate the Due Diligence process"]', '["Understanding the language of investors is key to scaling. This course pulls back the curtain on how Venture Capitalists think, from term sheets to valuation models.","We prepare you for the \\"Pitch Deck\\" journey, teaching you how to tell a financial story that secures the capital your business needs to expand internationally."]', 'OnSite', '$15k/month', '$180k - $400k', 11.2, '["Investment Banking","Private Equity","Angel Networks"]', 'cmp8kojvh0002lcpdktcx92y7'),
	('Mastering Applied AI and Machine Learning', 'mastering-applied-ai-and-machine-learning', 'Become a production-ready AI/ML engineer. Master Python, statistical modeling, Deep Learning, Natural Language Processing (NLP), and MLOps deployment architectures.', '/uploads/1779270847226-ktisfp.png', true, '2026-05-20 09:58:39.835', '2026-05-25 22:09:19.509', 'adaf9692-124b-4dbe-8bf2-ec0fc1be8d89', 'b429925a-1e38-4a61-9ae4-795bc1637bdb', 3, 150.00, '120 Hours', true, true, 'ADVANCED', 499.99, 10, '["Machine Learning Engineer","AI Data Scientist","Computer Vision Specialist","MLOps Deployment Engineer","NLP Research Analytics Developer"]', '["Build, evaluate, and tune robust regression, classification, and clustering models using Scikit-Learn","Design and train Deep Neural Networks for Computer Vision and NLP tasks using PyTorch","Deploy scalable machine learning models as clean APIs wrapped inside FastAPI and Docker containers","Build automated MLOps CI/CD pipelines to manage dataset tracking, model versioning, and execution drift","Optimize compute graphics resources and implement distributed model training architectures safely"]', '["The world is being fundamentally reshaped by Intelligent Systems. This intensive program bridges the gap between raw statistical academic theory and production-grade software deployment. You will start by understanding foundational linear algebra, probability, and standard machine learning frameworks (Scikit-Learn). From there, you will transition to Neural Networks, Advanced Computer Vision, and Transformer architectures using PyTorch.","Unlike courses that stop inside a Jupyter Notebook, this program trains you for real-world execution. You will build and configure automated ML engineering pipelines, monitor model drift, and scale deep learning algorithms in isolated container systems. By the end of this course, you will have constructed a robust professional portfolio comprising engineering models ready for commercial integration."]', 'Online', '$125,000 - $168,000', '$12,000 - $18,000', 32, '["FinTech & Algorithmic Quantitative Trading Firms","Autonomous Vehicles & Robotics Tech Hubs","Healthcare Infrastructure & Diagnostic Systems","Enterprise Cloud Computing & Big Data SaaS Products","E-Commerce Personalization Platforms"]', 'cmp8kn4u80001lcpdkabi1nhf'),
	('Career Guidance & Professional Orientation', 'career-guidance-professional-orientation-1', 'Are you confused about where you''re headed in your life? This 5-day intensive helps students and graduates uncover who they are, explore real career paths, and build a confident, disciplined plan for their future. More than information, it''s a transformation from uncertainty to purposeful direction, character, and leadership.', '/uploads/1789477931546-nwewec.png', true, '2026-09-15 13:12:21.21', '2026-09-17 19:52:41.369', 'f0ad1f10-7d8d-44bc-8277-68300e970ca8', '3e4ce107-02f9-4c65-b0f1-d49aa2939dac', 0, NULL, '5 days', true, true, 'BEGINNER', 0.00, 0, '{"Secondary School Students","High School Graduates","University Students","Recent Graduates Seeking Direction","Recent Graduates Seeking Direction","Parents & Guardians Supporting a Young Person''s Journey"}', '["Understand their personality, values, strengths, and passions","Distinguish between talent, skill, passion, and purpose","Navigate modern and emerging career opportunities with clarity","Apply a practical framework for confident career decision-making","Build a personal vision statement and a concrete career roadmap","Communicate and present themselves with professional confidence","Lead with character, discipline, and self-awareness"]', '["<p>Are you confused about where you&#039;re headed in your life? This 5-day intensive helps students and graduates uncover who they are, explore real career paths, and build a confident, disciplined plan for their future. More than information, it&#039;s a transformation from uncertainty to purposeful direction, character, and leadership.</p>"]', 'Online', NULL, NULL, NULL, '["Too many young people are academically trained but personally confused, choosing careers to please others, escape fear, or follow trends. In a fast-changing world of AI and shifting industries, self-awareness and disciplined decision-making are no longer optional; they are the foundation of a purposeful, resilient career."]', 'cmp8kn4u80001lcpdkabi1nhf'),
	('Personal and Impactful Leadership', 'personal-and-impactful-leadership', 'Leadership isn''t a title you''re given, it''s a life you build. This 5-day intensive develops the self-awareness, discipline, and character to lead yourself well, then equips you to influence, inspire, and lead others with integrity. Practical and transformational, built for anyone ready to lead before a title ever arrives.', '/uploads/1789942951351-t2jgpr.png', true, '2026-09-20 22:29:32.102', '2026-11-03 20:05:41.223', '6e71f4e7-07d8-4a92-bcb6-e5acb3c84bdf', '3e4ce107-02f9-4c65-b0f1-d49aa2939dac', 0, NULL, '5 days', true, true, 'BEGINNER', 0.00, 0, '["University Students & Recent Graduates","Young Professionals & Junior Staff","Entrepreneurs & Founders","Managers & Team Leaders","Youth & Community Leaders","Executives & Decision-Makers Seeking Deeper Influence"]', '["Distinguish leadership from management and identify your natural leadership style","Build self-awareness, self-discipline, and personal mastery","Develop character, integrity, and values-based decision-making","Apply emotional intelligence to strengthen relationships and influence","Craft a compelling personal vision and purpose-driven mission","Communicate with clarity, confidence, and persuasive impact","Lead high-performing teams through service and strategic thinking"]', '["<p>Leadership isn&#039;t a title you&#039;re given, it&#039;s a life you build. This 5-day intensive develops the self-awareness, discipline, and character to lead yourself well, then equips you to influence, inspire, and lead others with integrity. Practical and transformational, built for anyone ready to lead before a title ever arrives.</p>"]', 'Online', NULL, NULL, NULL, '["Organizations rarely lack talent, they lack people willing to lead with integrity, take responsibility, and serve others well. Impressive qualifications without character produce broken trust and disengaged teams. Mastering self-leadership first is what turns competence into lasting, trusted influence."]', 'cmp8kn4u80001lcpdkabi1nhf'),
	('STRATEGIC GOAL SETTING SKILLS FOR CAREER SUCCESS AND ORGANIZATIONAL GROWTH', 'strategic-goal-setting-skills-for-career-success-and-organizational-growth', 'Talent and hard work rarely fail on their own, lack of direction does. This 5-day intensive equips you with practical frameworks like SMART and 5W1H to turn vision into measurable goals, align effort with priorities, and execute with discipline, moving you from intention to real, tracked results.', '/uploads/1789903882049-t5cg65.png', true, '2026-09-20 11:35:27.604', '2026-11-03 20:05:20.472', '64e5da36-ad8b-4b01-93f6-d35775b52bd3', '3e4ce107-02f9-4c65-b0f1-d49aa2939dac', 0, NULL, '5 days', true, true, 'BEGINNER', 0.00, 0, '["University Students & Graduates","Young Professionals","Managers & Team Leaders","Entrepreneurs & Business Owners","Executives & Organizational Decision-Makers","Public Sector Professionals"]', '["Develop clear, measurable goals using the SMART and 5W1H frameworks","Align personal goals with organizational vision and strategic priorities","Apply SWOT, Balanced Scorecard, and Key Results tools to strategic planning","Prioritize goals and allocate time, resources, and talent effectively","Design a personal career vision, roadmap, and competency plan","Build accountability systems that turn plans into disciplined execution","Lead a goal-oriented culture that drives measurable organizational growth"]', '["<p>Talent and hard work rarely fail on their own, lack of direction does. This 5-day intensive equips you with practical frameworks like SMART and 5W1H to turn vision into measurable goals, align effort with priorities, and execute with discipline, moving you from intention to real, tracked results.</p>"]', 'Online', NULL, NULL, NULL, '["Many capable people know what they want but not how to get there, busy, yet not productive. Hard skills get you hired, but strategic goal setting gets you promoted, and disciplined execution makes you successful. Organizations reward measurable results, not activity alone."]', 'cmp8kn4u80001lcpdkabi1nhf'),
	('Critical thinking and emotional intelligence', 'critical-thinking-and-emotional-intelligence', 'Talent alone doesn''t guarantee career growth, clear thinking and emotional wisdom do. This 5-day intensive trains you to reason sharply under pressure, manage emotions and relationships well, and lead others with clarity and care. Practical, not theoretical, built for real decisions you''ll face starting Monday morning.', '/uploads/1789905917426-rmdi24.png', true, '2026-09-20 12:08:00.598', '2026-11-03 20:05:26.798', '283cec1e-88e9-4724-b6aa-d80c4e97698e', '3e4ce107-02f9-4c65-b0f1-d49aa2939dac', 0, NULL, '5 days', true, true, 'BEGINNER', 0.00, 0, '["Employees & Team Members","Managers & Supervisors","Team Leaders & Department Heads","Entrepreneurs & Business Owners","Young Professionals & University Graduates","Executives Driving Organizational Change"]', '["Apply structured reasoning to solve complex workplace problems","Recognize and overcome cognitive biases that distort decisions","Build self-awareness, self-regulation, and emotional control under pressure","Communicate with empathy and manage relationships with confidence","Use practical tools such as Root Cause Analysis, SWOT, and Decision Matrices","Coach, give feedback, and resolve conflict with clarity and care","Lead teams and organizational change with emotional intelligence"]', '["<p>Talent alone doesn&#039;t guarantee career growth, clear thinking and emotional wisdom do. This 5-day intensive trains you to reason sharply under pressure, manage emotions and relationships well, and lead others with clarity and care. Practical, not theoretical, built for real decisions you&#039;ll face starting Monday morning.</p>"]', 'Online', NULL, NULL, NULL, '["Too many careers stall, not from lack of talent, but from rushed decisions, unchecked bias, and emotions that damage trust. Employers now value reasoning and emotional intelligence above technical certificates, because these skills transfer across every role, tool, and challenge."]', 'cmp8kn4u80001lcpdkabi1nhf'),
	('Strategic communication skills in working environment', 'strategic-communication-skills-in-working-environment', 'Competence gets you hired, strategic communication gets you trusted, promoted, and remembered. This 5-day intensive builds the frameworks to present ideas with confidence, disagree respectfully, give feedback that motivates, and communicate through change with clarity, turning your ideas from invisible to influential.', '/uploads/1789945481880-a42ro8.png', true, '2026-09-20 23:13:40.445', '2026-11-03 20:05:46.397', 'd9d49d3e-fa01-43a1-a7cc-3772d62eb3ea', '3e4ce107-02f9-4c65-b0f1-d49aa2939dac', 0, NULL, '5 days', true, true, 'BEGINNER', 0.00, 0, '["University Graduates Entering the Workplace","Junior Staff & New Employees","Supervisors & Team Leaders","Managers & Middle Management","Entrepreneurs & Business Owners","Executives Seeking Stronger Influence"]', '["Apply the five characteristics of strategic communication to real conversations","Build high-trust relationships through active listening and empathy","Disagree with leaders respectfully using the S.A.F.E. framework","Present ideas to leadership with structure, evidence, and confidence","Deliver feedback that motivates using the DIGNITY Model and Feedback Formula","Navigate difficult conversations and organizational change with composure","Build a consistent, trustworthy professional communication brand"]', '["<p>Competence gets you hired, strategic communication gets you trusted, promoted, and remembered. This 5-day intensive builds the frameworks to present ideas with confidence, disagree respectfully, give feedback that motivates, and communicate through change with clarity, turning your ideas from invisible to influential.</p>"]', 'Online', NULL, NULL, NULL, '["Too many careers stall for reasons unrelated to competence, an idea poorly presented, feedback delivered so harshly it destroys motivation, or a vision never clearly explained. Strategic communication is a trainable leadership capability, and mastering it determines who gets trusted, promoted, and followed."]', 'cmp8kn4u80001lcpdkabi1nhf'),
	('Entrepreneurship and Creative Thinking', 'entrepreneurship-and-creative-thinking', 'Waiting for a job is no longer a strategy, but creating value is. This 5-day intensive builds the entrepreneurial mindset: spotting real opportunities, thinking creatively, solving problems others overlook, and turning ideas into sustainable ventures. Practical, disciplined, and built for people ready to become creators, not just job-seekers.', '/uploads/1790379974025-id2h4f.png', true, '2026-09-25 23:46:23.474', '2026-11-03 20:05:55.808', '12e98d8f-3d6e-4db1-beba-9ded01f8a6d1', '3e4ce107-02f9-4c65-b0f1-d49aa2939dac', 0, NULL, '5 days', true, true, 'BEGINNER', 0.00, 0, '["University Students & Graduates","Aspiring Entrepreneurs & Freelancers","Young Professionals Exploring New Ventures","Innovators & Product Developers","Small Business Owners","Community & Youth Leaders Driving Local Enterprise"]', '["Apply creative and design thinking to generate original solutions","Discover, validate, and select genuinely worthwhile opportunities","Create real customer value before chasing profit","Navigate risk and make wise decisions under uncertainty","Build credibility, a personal brand, and strategic partnerships","Lead with confidence, communicate persuasively, and negotiate effectively","Design a personal, disciplined entrepreneurial action blueprint"]', '["<p>Waiting for a job is no longer a strategy, but creating value is. This 5-day intensive builds the entrepreneurial mindset: spotting real opportunities, thinking creatively, solving problems others overlook, and turning ideas into sustainable ventures. Practical, disciplined, and built for people ready to become creators, not just job-seekers.</p>"]', 'Online', NULL, NULL, NULL, '["Formal employment can no longer absorb every capable graduate, yet unsolved problems surround us, unmonetised, ignored, waiting for someone to act. Entrepreneurial thinking turns constraint into opportunity, transforming job-seekers into value-creators and building the confidence, creativity, and discipline every career and venture demands."]', 'cmp8kn4u80001lcpdkabi1nhf'),
	('Strategic Teamwork and Networking', 'strategic-teamwork-and-networking', 'No career or organization succeeds alone. This 5-day intensive builds relationship capital, the trust, teamwork, and strategic connections that accelerate opportunity. Learn to lead high-performing teams, network with purpose, and turn contacts into lasting partnerships that open doors qualifications alone cannot.', '/uploads/1790386259766-abn2lw.png', true, '2026-09-26 01:31:05.804', '2026-11-03 20:06:03.971', '01653ae7-a22b-44c3-8715-8bb89f227017', '3e4ce107-02f9-4c65-b0f1-d49aa2939dac', 0, NULL, '5 days', true, true, 'BEGINNER', 0.00, 0, '["University Students & Graduates","Young Professionals & Job Seekers","Team Leaders & Managers","Entrepreneurs & Start-Up Founders","Executives & CEOs","Youth & Organizational Changemakers"]', '["Build trust and relationship capital through credibility and consistency","Distinguish ordinary teamwork from strategic, results-driven collaboration","Lead high-performing teams through shared vision and accountability","Apply the Strategic Networking Pyramid to deepen professional relationships","Network with generosity, building value before requesting it","Strengthen personal branding to increase professional credibility","Design a personal Strategic Networking and Partnership Growth Blueprint"]', '["<p>No career or organization succeeds alone. This 5-day intensive builds relationship capital, the trust, teamwork, and strategic connections that accelerate opportunity. Learn to lead high-performing teams, network with purpose, and turn contacts into lasting partnerships that open doors qualifications alone cannot.</p>"]', 'Online', NULL, NULL, NULL, '["Too many careers stall not from a lack of skill, but a lack of relationships, and too many organizations plateau not from a lack of resources, but a lack of trust-based collaboration. In a hyper-connected world, relationship capital is the deciding factor competence alone cannot supply."]', 'cmp8kn4u80001lcpdkabi1nhf'),
	('Personal Development and Career Growth', 'personal-development-and-career-growth', 'A degree alone no longer guarantees opportunity, presence, communication, and character now decides who gets hired and promoted. This 5-day intensive builds an attractive professional identity, teaches you to market your value, and equips you to grow deliberately from entry-level employee toward trusted leader.', '/uploads/1789900310581-t41ild.png', true, '2026-09-20 10:35:37.808', '2026-11-03 20:05:11.812', '04c467e6-000e-40ef-b1ee-f8da1d69925e', '3e4ce107-02f9-4c65-b0f1-d49aa2939dac', 0, NULL, '5 days', true, true, 'BEGINNER', 0.00, 0, '["University Graduates Entering the Job Market","Active Job Seekers","Entry-Level Employees","Young Professionals & Career Starters","Managers & Team Leaders Mentoring Rising Talent"]', '{"Build a confident, trustworthy professional personality and presence","Communicate and market their value through CV, interview, and digital brand","Distinguish genuine confidence from arrogance in the workplace","Apply emotional intelligence to stay composed and trusted under pressure","Navigate today''s labour market and identify in-demand, transferable skills","Design a personal development plan and career growth roadmap","Begin thinking and acting like a future leader from their current role"}', '{"<p>A degree alone no longer guarantees opportunity, presence, communication, and character now decides who gets hired and promoted. This 5-day intensive builds an attractive professional identity, teaches you to market your value, and equips you to grow deliberately from entry-level employee toward trusted leader.
INSERT INTO `Certificate` (`id`, `userId`, `courseId`, `issueDate`, `certificateNumber`, `grade`, `finalScore`) VALUES
