INSERT INTO `Module` (`title`, `description`, `id`, `courseId`, `createdAt`, `order`, `updatedAt`) VALUES
	('Module 4: Data-Driven Execution', 'How to leverage AI and big data analytics to validate your intuition before committing capital.', 'a876de73-1603-4d55-97bd-543e5e5a9f43', '41e9c0f6-6b32-401a-bdf0-9d404343157c', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Module 3: Bias Mitigation', 'A practical guide to spotting the "Sunk Cost Fallacy" and "Confirmation Bias" in board meetings.', 'ed62b90a-ee80-4846-a4be-ccfe1927bdd3', '41e9c0f6-6b32-401a-bdf0-9d404343157c', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Module 2: Strategic Frameworks', 'Implementing the Eisenhower Matrix and McKinsey’s 7S framework to prioritize organizational objectives.', 'f14159af-eb56-4c1e-8b4d-d3de33532a3f', '41e9c0f6-6b32-401a-bdf0-9d404343157c', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Module 1: The Psychology of Choice', 'Understanding how the brain processes risk and reward under extreme pressure and time constraints.', 'af451a26-a4bf-424f-aa0e-724cf3bd6668', '41e9c0f6-6b32-401a-bdf0-9d404343157c', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Psychological Safety', 'Building a culture where team members feel safe to take risks and speak up.', '48453cc0-35f0-41f9-93e4-b425d75ac1e2', '3167514a-8148-4789-a95b-15ee856f2772', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Conflict Resolution', 'Mastering the art of difficult conversations and Radical Candor.', '7d894452-2daf-4480-bf3d-6f2577a15fca', '3167514a-8148-4789-a95b-15ee856f2772', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Agile Leadership', 'Moving from command-and-control to servant leadership and Scrum cycles.', 'f406e65a-3fdc-44bc-97aa-34393fdf4c79', '3167514a-8148-4789-a95b-15ee856f2772', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Sustaining Motivation', 'The science of intrinsic motivation and high-retention culture building.', 'ad669482-0373-470e-af53-04a1830da358', '3167514a-8148-4789-a95b-15ee856f2772', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Self-Awareness Tools', 'Developing the internal radar to monitor emotional triggers in real-time.', '6d0349fa-84c3-4788-96f9-790fa627df38', 'a3e7130c-e092-4f5f-82ed-ab2bbab34485', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Empathy in Management', 'Techniques for active listening and understanding unstated team needs.', '2eef929c-48fe-468a-9dbd-e01ad88c9b7b', 'a3e7130c-e092-4f5f-82ed-ab2bbab34485', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Influence Without Authority', 'How to lead cross-functional teams and stakeholders using social capital.', '9cb15462-ca66-4072-b7b5-7c5abd8e5f49', 'a3e7130c-e092-4f5f-82ed-ab2bbab34485', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Resilience Coaching', 'Managing personal stress and team burnout during high-stakes projects.', '53df054a-525d-4f5e-8940-2fbb3ed3591c', 'a3e7130c-e092-4f5f-82ed-ab2bbab34485', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('The Dynamics of Change', 'Applying Kotters 8-Step process to organizational transformation.', '373f422c-ed7a-4434-8b31-60dcd1206065', 'd5d208c9-6b35-4185-8eb8-1d9d2301efbe', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Stakeholder Alignment', 'Mapping influence and interest to overcome resistance at every level.', '4024eb3a-4170-4259-8d2e-515a51a5feb4', 'd5d208c9-6b35-4185-8eb8-1d9d2301efbe', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Communication Strategy', 'Crafting transparent narratives that maintain morale during restructuring.', 'eba14885-8130-4998-b7e0-463b02c6f0b0', 'd5d208c9-6b35-4185-8eb8-1d9d2301efbe', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Measuring Transformation', 'Defining KPIs and success metrics for non-linear organizational shifts.', 'a6bdccb3-9fb0-4f58-b98c-855eec7d7a84', 'd5d208c9-6b35-4185-8eb8-1d9d2301efbe', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('The Pirate Metrics (AARRR)', 'Mastering the funnel from Acquisition and Activation to Revenue and Referral.', '87c592a4-151e-450c-888a-d0194571af95', '810523d8-6cf8-4fbc-9af6-a27d2133f0d6', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Rapid Prototyping', 'Building smokescreen tests to validate product demand in 24 hours.', 'f678906f-60bc-4312-9060-6e3049c0aeeb', '810523d8-6cf8-4fbc-9af6-a27d2133f0d6', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Viral Loop Engineering', 'Designing product features that encourage users to invite other users.', '6d34449c-6827-46f5-9b88-62e263145d89', '810523d8-6cf8-4fbc-9af6-a27d2133f0d6', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Retention Analytics', 'How to identify the Aha! Moment that keeps users coming back forever.', '9a10f549-8ccc-46cf-955d-20b708bd4d3d', '810523d8-6cf8-4fbc-9af6-a27d2133f0d6', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Technical SEO Audit', 'Optimizing site architecture, crawl budget, and Core Web Vitals.', '8da863a7-602c-43f4-a168-2be3f9ba8424', 'e7d4e4c0-32e1-4e6e-9a73-fe59d2227ad6', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Topical Authority', 'Building content clusters that dominate search engine results pages.', '5bdc2181-c0b4-4c02-8e38-1d86d1270625', 'e7d4e4c0-32e1-4e6e-9a73-fe59d2227ad6', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Semantic Search & AI', 'How search engines understand intent and how to optimize for it.', '56dfc625-39d0-4507-883c-31c6b7b2310e', 'e7d4e4c0-32e1-4e6e-9a73-fe59d2227ad6', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Backlink Ecosystems', 'Strategic link-earning through high-value networking and PR.', '0371cad3-559c-4d7c-a34d-e69adafa7c29', 'e7d4e4c0-32e1-4e6e-9a73-fe59d2227ad6', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Brand Storytelling', 'Developing a unique voice that cuts through the noise of AI-generated content.', '32c49a39-3e0c-400f-8906-b70d0fa6e082', 'd96d9df2-e34c-42f9-b800-a5f3dc244b16', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('The Content Pillar System', 'Efficiency in repurposing long-form content across multiple platforms.', '735543d2-f331-4198-8196-03274a11c341', 'd96d9df2-e34c-42f9-b800-a5f3dc244b16', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Lead Magnet Design', 'Creating value-driven assets that convert anonymous visitors into leads.', 'f9915135-e2c9-4c9c-b80d-0bfd12405b07', 'd96d9df2-e34c-42f9-b800-a5f3dc244b16', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Editorial Management', 'Building a scalable content calendar and managing freelance workflows.', '79daa7d3-d9c7-4335-b556-3fcec9aa8930', 'd96d9df2-e34c-42f9-b800-a5f3dc244b16', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Conversion Tracking', 'Setting up advanced pixels and GTM tags to measure true campaign ROI.', '5359d79e-25e2-41dc-960e-9150a91df747', '58a222cf-03ca-4fc2-91e9-9d92be85917a', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Audience Modeling', 'Leveraging first-party data to build high-converting lookalike audiences.', '5fd9a618-7c63-4036-bc43-8ff52876165e', '58a222cf-03ca-4fc2-91e9-9d92be85917a', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Attribution Logic', 'Understanding the journey from first-click to last-click in complex sales.', '9a010987-78f6-47bf-b936-5de38e239156', '58a222cf-03ca-4fc2-91e9-9d92be85917a', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Budget Optimization', 'Algorithmic scaling and manual bid strategies for maximum efficiency.', 'd072cc3d-7a6d-4649-9dc9-98f031a9a25d', '58a222cf-03ca-4fc2-91e9-9d92be85917a', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('The Build-Measure-Learn Loop', 'Eliminating waste by validating ideas through rapid experimentation.', 'e8b8b1ac-53af-447f-9da4-0c740adae579', '31b32592-7c01-46fc-b9de-274f1ab2298f', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('The Mom Test', 'Mastering customer discovery interviews so users dont lie to you.', '85787a0a-6b4d-4f7c-bd1d-0209d7db561f', '31b32592-7c01-46fc-b9de-274f1ab2298f', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('MVP Development', 'How to strip a product to its core value proposition for early launch.', 'c50cff56-fb73-4aef-8a9a-bc63a624b642', '31b32592-7c01-46fc-b9de-274f1ab2298f', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('The Pivot Logic', 'Knowing when to change strategy based on cold market evidence.', '0e6804ea-fde9-4ba5-b159-8722d9194496', '31b32592-7c01-46fc-b9de-274f1ab2298f', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('The Pitch Deck Anatomy', 'Crafting a narrative that addresses investor concerns and market size.', 'b90dc193-660d-4e35-92e4-017e7930f126', 'bd7f57ac-14aa-4c2e-8387-77f4bdd69564', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Term Sheet Fundamentals', 'Understanding equity, dilution, and liquidation preferences.', '9316ce21-7141-444c-b7ce-867a81f1261e', 'bd7f57ac-14aa-4c2e-8387-77f4bdd69564', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Valuation Models', 'Determining the worth of a pre-revenue startup using industry standards.', 'abc21873-6fa6-4fcd-b11d-f8ffb8a07892', 'bd7f57ac-14aa-4c2e-8387-77f4bdd69564', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Due Diligence Readiness', 'Organizing data rooms and legal docs for institutional investment.', '078e18fb-01d4-4641-bf55-75fe2355be59', 'bd7f57ac-14aa-4c2e-8387-77f4bdd69564', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('The Business Model Canvas', 'Mapping the 9 building blocks of a successful organizational structure.', 'a4fff9cf-93d2-4b79-b643-917d6536e1c4', '4ed14083-f09a-4f89-a57b-bb579b041eb2', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Revenue Stream Innovation', 'Moving from one-time sales to recurring and platform-based income.', '34b9d5c0-b729-4db5-8cd4-f0c45c2d710c', '4ed14083-f09a-4f89-a57b-bb579b041eb2', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Value Proposition Design', 'Aligning product features with specific, high-value customer pains.', 'edcb0f5f-913f-4b8e-9705-a578300f8698', '4ed14083-f09a-4f89-a57b-bb579b041eb2', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Disruptive Strategies', 'Analyzing how lean startups unseat established industry giants.', 'c9a94c2a-d8ce-43fe-8171-28ee17f7a4e3', '4ed14083-f09a-4f89-a57b-bb579b041eb2', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Systems & SOPs', 'Documenting standard operating procedures to ensure quality at scale.', 'a12d5ba8-f84e-4a59-85e3-f0849841c919', '6fb6a9dc-ac2a-486c-b2f9-5297814b60fd', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Automation Architecture', 'Leveraging low-code tools to run a business with minimal overhead.', 'd3a4bfb8-fb59-4f05-aee5-3f4fb857ade9', '6fb6a9dc-ac2a-486c-b2f9-5297814b60fd', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Talent Acquisition', 'Building a recruitment engine that identifies cultural and skill fits.', 'd87e8be7-a629-419a-a5f1-4dafba04a903', '6fb6a9dc-ac2a-486c-b2f9-5297814b60fd', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Financial Controls', 'Monitoring burn rate and cash flow to ensure long-term sustainability.', '5dfd4456-99f3-4414-871f-05d715c2bdf2', '6fb6a9dc-ac2a-486c-b2f9-5297814b60fd', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Foundations of Data Engineering and Exploratory Analytics', 'Master the essential libraries and techniques used to prepare messy data for predictive models. This module covers setting up optimized runtime environments, vector computation with NumPy, data manipulation using Pandas, and identifying statistical trends through visual exploratory data analysis (EDA).', 'f7689519-c1a1-416e-8f7a-b2ed39cfb185', 'adaf9692-124b-4dbe-8bf2-ec0fc1be8d89', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Supervised Learning Algorithms and Mathematical Frameworks', 'Deep dive into the mechanics of predictive modeling. You will explore classical linear algorithms, regression models, classification paradigms, and cost optimization techniques like Gradient Descent. Learn how to prevent overfitting and safely validate data splits using Scikit-Learn.', 'f26b3d15-ba2c-494a-af36-f6b0e2d1b778', 'adaf9692-124b-4dbe-8bf2-ec0fc1be8d89', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Ensemble Methods and Advanced Non-Parametric Modeling', 'Move beyond single linear equations to exploit complex multi-decision structures. This module handles non-parametric systems including Decision Trees, Random Forests, Support Vector Machines (SVMs), and cutting-edge high-performance gradient boosting frameworks such as XGBoost and LightGBM.', '2e512d6f-0e8f-405c-b3b1-7b92f838bdbf', 'adaf9692-124b-4dbe-8bf2-ec0fc1be8d89', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Unsupervised Extraction and Dimensionality Reduction Techniques', 'Learn how to uncover hidden patterns within completely unlabelled datasets. Master clustering mechanics using K-Means and Hierarchical paradigms alongside core engineering dimensionality extraction methods like Principal Component Analysis (PCA) and t-SNE to condense massive feature matrices.', '3dc1b193-f8fc-455a-9149-5942e7690c88', 'adaf9692-124b-4dbe-8bf2-ec0fc1be8d89', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Introduction to Deep Learning and Core Neural Networks', 'Transition into high-dimensional cognitive computation systems. This module introduces biological-mimicking models, training networks with PyTorch, manipulating abstract multi-dimensional Tensors, evaluating backpropagation cost paths, and optimizing weight structures to handle non-linear problems.', 'a4e11a6c-2faf-4eca-9218-5f1ccfc1d4cf', 'adaf9692-124b-4dbe-8bf2-ec0fc1be8d89', '2026-09-17 09:51:02.125', 0, '2026-09-17 09:51:02.125'),
	('Understanding Yourself Before Choosing a Career', '<h2>Before choosing a career, discover who you are.</h2>
INSERT INTO `Lesson` (`id`, `title`, `slug`, `content`, `order`, `moduleId`, `createdAt`, `updatedAt`) VALUES
	('184bcb25-1d0d-45c2-b51a-3d8f2e5b2dca', 'Discovering the Roots of Nonviolent Communication', 'discovering-the-roots-of-nonviolent-communication', '{"type": "doc", "content": [{"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"align": null, "colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"text": "★  THE BIG IDEA", "type": "text", "marks": [{"type": "bold"}, {"type": "lessonTextStyle", "attrs": {"color": "darkgoldenrod", "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "“Underneath every judgment is a need waiting to be honoured.”", "type": "text", "marks": [{"type": "bold"}, {"type": "italic"}, {"type": "lessonTextStyle", "attrs": {"color": "rgb(31, 56, 100)", "fontSize": "48px"}}]}]}]}]}]}, {"type": "paragraph", "content": [{"text": " ", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "What Nonviolent Communication Actually Means", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "Nonviolent Communication, often called NVC, is both a way of thinking and a practical method for expressing yourself honestly and hearing others empathically, even in the middle of disagreement. “Nonviolent” here does not only mean the absence of physical harm; it means communication free of the subtler violence of blame, shame, guilt, coercion, and contempt: the words that wound without ever raising a fist.", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "NVC rests on a simple but radical assumption: every human being, however they are behaving, is trying to meet a genuine human need. When we can see the need beneath the behaviour, our own and other people''s, conflict stops being a battle to win and becomes a puzzle to solve together.", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Life-Alienating Communication", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "Life-alienating communication is any way of speaking that disconnects us from our own compassion and from one another. It typically takes four forms: moralistic judgments (labelling people as good, bad, lazy, selfish); comparisons (measuring ourselves or others against an ideal); denial of responsibility (“You made me do it”, “I had no choice”); and demands (communicating in a way that implies blame or punishment if a request is not met).", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "None of these forms make someone a bad person for using them; they are simply the default language most of us were taught before we ever learned an alternative.", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Life-Serving Communication", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "Life-serving communication, by contrast, is language that keeps everyone''s humanity in view, even during disagreement. It observes without judging, names feelings honestly, connects those feelings to real needs, and makes clear, doable requests rather than disguised demands. The goal is never to suppress honesty for the sake of politeness; it is to be radically honest in a way that keeps the door to connection open rather than slamming it shut.", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Why This Shift Changes Everything", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "Most conflict is not actually about the surface disagreement: the dishes, the deadline, the curfew. It is about unmet needs colliding: for respect, for rest, for autonomy, for being seen. When two people argue about the surface issue without ever naming the need underneath, they can debate for hours and still leave feeling unheard. NVC does not ask you to abandon your position; it asks you to discover what you are truly needing, and to help the other person discover the same, so a real solution becomes possible.", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Where This Approach Came From", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "Nonviolent Communication was developed by the psychologist Marshall B. Rosenberg, who spent decades working in some of the most divided and conflict-affected communities in the world, from school desegregation efforts in the United States to peace-building work across the Middle East and Africa. His central discovery, repeated across very different cultures, was strikingly consistent: however different people''s languages, religions, or histories, the underlying human needs driving their words were remarkably similar.", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "This history matters because it reminds participants that NVC was never designed as a soft, Western self-help trend; it was forged in rooms where people were actively in conflict, and tested against real, high-stakes disagreement long before it became a course like this one.", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "Life-Alienating vs. Life-Serving Communication", "type": "text", "marks": [{"type": "bold"}, {"type": "italic"}, {"type": "lessonTextStyle", "attrs": {"color": "rgb(31, 56, 100)", "fontSize": "48px"}}]}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"align": null, "colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"text": "Life-Alienating Communication", "type": "text", "marks": [{"type": "bold"}, {"type": "lessonTextStyle", "attrs": {"color": "#050505", "fontSize": "48px"}}]}]}]}, {"type": "tableCell", "attrs": {"align": null, "colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"text": "Life-Serving Communication (NVC)", "type": "text", "marks": [{"type": "bold"}, {"type": "lessonTextStyle", "attrs": {"color": "#100f0f", "fontSize": "48px"}}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"align": null, "colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"text": "Judges people as good or bad, right or wrong", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}]}, {"type": "tableCell", "attrs": {"align": null, "colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"text": "Observes specific actions without labelling character", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"align": null, "colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"text": "Compares people against an ideal or against each other", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}]}, {"type": "tableCell", "attrs": {"align": null, "colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"text": "Notices each person''s unique feelings and needs", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"align": null, "colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"text": "Denies responsibility (“You made me feel...”)", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}]}, {"type": "tableCell", "attrs": {"align": null, "colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"text": "Owns feelings as arising from one''s own needs", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"align": null, "colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"text": "Demands, with implied blame or punishment", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}]}, {"type": "tableCell", "attrs": {"align": null, "colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"text": "Requests clearly, leaving room for a genuine ‘no’", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"align": null, "colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"text": "Aims to win the argument", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}]}, {"type": "tableCell", "attrs": {"align": null, "colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"text": "Aims to meet everyone''s needs, including one''s own", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Sentence Starters to Practise This Week", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "•     ", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}, {"text": "“What I''m noticing is... (fact only, no label)”", "type": "text", "marks": [{"type": "italic"}, {"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "•     ", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}, {"text": "“I''m guessing there''s a need underneath what you just said, am I right?”", "type": "text", "marks": [{"type": "italic"}, {"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "•     ", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}, {"text": "“Instead of judging this, let me describe exactly what happened.”", "type": "text", "marks": [{"type": "italic"}, {"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "•     ", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}, {"text": "“I don''t think either of us is wrong here; we may just have different needs.”", "type": "text", "marks": [{"type": "italic"}, {"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "•     ", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}, {"text": "“Can I take responsibility for my feeling instead of blaming you for it?”", "type": "text", "marks": [{"type": "italic"}, {"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": " ", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"align": null, "colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"text": "✋  REAL-LIFE SNAPSHOT", "type": "text", "marks": [{"type": "bold"}, {"type": "lessonTextStyle", "attrs": {"color": "rgb(31, 56, 100)", "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "Angel", "type": "text", "marks": [{"type": "bold"}, {"type": "italic"}, {"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "Angel grew up believing that expressing anger meant raising your voice until the other person backed down. In a training session she attended, a facilitator asked her to translate her go-to line, “You never listen to me!”, into an observation, a feeling, and a need. She sat in uncomfortable silence for almost a minute before she could say, “When I was talking and you looked at your phone, I felt hurt, because I need to feel that I matter in this conversation.” The words felt strange in her mouth the first few times, but the response she received, for the first time in years, was not defensiveness. It was an apology.", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}]}]}]}, {"type": "paragraph", "content": [{"text": " ", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"align": null, "colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"text": "✎  PRACTICAL APPLICATION", "type": "text", "marks": [{"type": "bold"}, {"type": "lessonTextStyle", "attrs": {"color": "rgb(138, 109, 0)", "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "TRANSLATION EXERCISE", "type": "text", "marks": [{"type": "bold"}, {"type": "italic"}, {"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "Write down a criticism you have made recently (to yourself or someone else). Rewrite it without a single judgment word: describing only what happened, what you felt, and what you needed.", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}]}]}]}, {"type": "paragraph", "content": [{"text": " ", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableCell", "attrs": {"align": null, "colspan": 1, "rowspan": 1, "colwidth": null}, "content": [{"type": "paragraph", "content": [{"text": "✨  REFLECTION QUESTIONS", "type": "text", "marks": [{"type": "bold"}, {"type": "lessonTextStyle", "attrs": {"color": "rgb(31, 56, 100)", "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "1.  ", "type": "text", "marks": [{"type": "bold"}, {"type": "lessonTextStyle", "attrs": {"color": "darkgoldenrod", "fontSize": "48px"}}]}, {"text": "Which of the four forms of life-alienating communication (judging, comparing, denying responsibility, demanding) do I use most often?", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "2.  ", "type": "text", "marks": [{"type": "bold"}, {"type": "lessonTextStyle", "attrs": {"color": "darkgoldenrod", "fontSize": "48px"}}]}, {"text": "What need might be hiding underneath a judgment I have made recently about someone?", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "3.  ", "type": "text", "marks": [{"type": "bold"}, {"type": "lessonTextStyle", "attrs": {"color": "darkgoldenrod", "fontSize": "48px"}}]}, {"text": "Have I ever assumed someone''s behaviour meant they did not care about me, when it may have meant something else?", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "4.  ", "type": "text", "marks": [{"type": "bold"}, {"type": "lessonTextStyle", "attrs": {"color": "darkgoldenrod", "fontSize": "48px"}}]}, {"text": "What would it cost me to stop assigning blame in my next disagreement?", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "5.  ", "type": "text", "marks": [{"type": "bold"}, {"type": "lessonTextStyle", "attrs": {"color": "darkgoldenrod", "fontSize": "48px"}}]}, {"text": "When did someone last make a request of me that actually sounded like a demand? How did I respond?", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "6.  ", "type": "text", "marks": [{"type": "bold"}, {"type": "lessonTextStyle", "attrs": {"color": "darkgoldenrod", "fontSize": "48px"}}]}, {"text": "What is one moralistic label (lazy, selfish, difficult) that I apply to myself too easily?", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "7.  ", "type": "text", "marks": [{"type": "bold"}, {"type": "lessonTextStyle", "attrs": {"color": "darkgoldenrod", "fontSize": "48px"}}]}, {"text": "How might my closest relationship change if both people stopped comparing each other to an ideal?", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "8.  ", "type": "text", "marks": [{"type": "bold"}, {"type": "lessonTextStyle", "attrs": {"color": "darkgoldenrod", "fontSize": "48px"}}]}, {"text": "What would ''life-serving'' communication sound like in a conversation I am currently avoiding?", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}]}]}]}, {"type": "paragraph", "content": [{"text": " ", "type": "text", "marks": [{"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}, {"type": "paragraph", "content": [{"text": "KEY LESSON  ", "type": "text", "marks": [{"type": "bold"}, {"type": "lessonTextStyle", "attrs": {"color": "rgb(31, 56, 100)", "fontSize": "48px"}}]}, {"text": "Every judgment is a tragic expression of an unmet need. Learn to hear the need, and the judgment loses its power.", "type": "text", "marks": [{"type": "italic"}, {"type": "lessonTextStyle", "attrs": {"color": null, "fontSize": "48px"}}]}]}]}', 2, '8fe2f30e-d2c5-42a0-a4e3-d8c54e4725ed', '2026-10-07 08:15:01.771', '2026-10-08 15:03:23.422'),
	('9302cc36-04dc-4530-adf9-834b99b5104f', 'Setting Up Your Production Environment with Anaconda and VS Code', 'setting-up-your-production-environment-with-anaconda-and-vs-code', '[{"text": "Setting Up Your Production Environment with Anaconda and VS Code", "type": "heading", "level": 1}, {"text": "Learn how to create a reproducible, production-ready data science environment using Anaconda for package and environment management, paired with VS Code as your development IDE. This lesson covers installation, environment configuration, dependency management, and best practices for production deployments.", "type": "paragraph"}, {"url": "https://www.youtube.com/embed/dQw4w9WgXcQ", "type": "video", "caption": "Why Anaconda and VS Code? – Overview of Production Environments"}, {"text": "Installing Anaconda Distribution", "type": "heading", "level": 2}, {"text": "Download Anaconda from the official repository (or use Miniconda for a lighter install). Run the installer and follow the platform-specific instructions. After installation, verify it by opening a terminal or Anaconda Prompt and running the commands below.", "type": "paragraph"}, {"code": "conda --version\nconda info", "type": "code", "language": "bash"}, {"type": "list", "items": ["Windows 10/11 (64-bit) or macOS 10.15+ / Linux (Ubuntu 20.04+)", "4 GB RAM minimum (8 GB recommended)", "5 GB free disk space", "Administrator privileges (for installation)"], "style": "unordered"}, {"alt": "Anaconda Navigator interface showing environments and tools", "url": "https://cdn.lms.example.com/anaconda-navigator.png", "type": "image"}, {"text": "Creating and Managing Conda Environments", "type": "heading", "level": 2}, {"text": "Environments isolate dependencies for different projects. For production, create a dedicated environment with a specific Python version. Use `conda create` followed by `conda activate` to switch.", "type": "paragraph"}, {"code": "conda create --name prod_env python=3.9\nconda activate prod_env", "type": "code", "language": "bash"}, {"rows": [["Conda", "Built‑in environments, binaries, easy C extensions", "Slower resolve times, large install size"], ["venv", "Lightweight, Python‑native", "No non‑Python packages, manual path management"], ["pipenv", "Lock file, deterministic builds", "Slower, less mature for data science libs"]], "type": "table", "headers": ["Tool", "Advantages", "Disadvantages"]}, {"text": "Always export your environment to an `environment.yml` file. This allows teammates or production servers to recreate the exact setup with `conda env create -f environment.yml`.", "type": "callout", "intent": "info"}, {"text": "Configuring VS Code for Conda Environments", "type": "heading", "level": 2}, {"text": "Open your project folder in VS Code. Install the Python extension by Microsoft. Then select the conda environment you just created as the Python interpreter.", "type": "paragraph"}, {"alt": "VS Code command palette showing ''Python: Select Interpreter'' and a list of conda envs", "url": "https://cdn.lms.example.com/vscode-select-interpreter.png", "type": "image"}, {"type": "list", "items": ["Press Ctrl+Shift+P (Cmd+Shift+P on macOS) to open Command Palette", "Type ''Python: Select Interpreter''", "Choose the interpreter path that contains your conda environment (e.g., `./opt/anaconda3/envs/prod_env/bin/python`)"], "style": "ordered"}, {"url": "https://www.youtube.com/embed/dQw4w9WgXcQ", "type": "video", "caption": "Step‑by‑Step: Connect VS Code to a Conda Environment"}, {"text": "Installing Production Dependencies", "type": "heading", "level": 2}, {"text": "Add packages using `conda install` whenever possible. For packages not available in conda channels, use `pip` but after conda installs to avoid conflicts. Pin critical versions.", "type": "paragraph"}, {"code": "conda install numpy pandas scikit-learn=1.0.2\npip install ''some-conda-missing-package>=2.0''", "type": "code", "language": "bash"}, {"rows": [["pandas", "Data manipulation", ">=1.3.0,<2.0.0"], ["scikit-learn", "Machine learning", "1.0.2"], ["fastapi", "API serving (if needed)", ">=0.85.0"], ["pytest", "Testing", ">=7.0.0"]], "type": "table", "headers": ["Package", "Purpose", "Version Pinning Example"]}, {"text": "Avoid mixing `conda` and `pip` arbitrarily. Prefer conda for core numeric and ML libraries. Use pip only when a package is unavailable in conda channels, and always install conda packages first.", "type": "callout", "intent": "warning"}, {"text": "Setting Up Environment Variables and Secrets", "type": "heading", "level": 2}, {"text": "Production code often requires API keys, database URLs, or other secrets. Never hard‑code them. Use `.env` files and the `python-dotenv` package to load variables, and ensure `.env` is in `.gitignore`.", "type": "paragraph"}, {"type": "list", "items": ["Store secrets in environment variables, not in code.", "Use VS Code extension ''DotENV'' for syntax highlighting.", "Add `.env` to your `.gitignore` file.", "Provide a `.env.example` file with dummy values as a template."], "style": "unordered"}, {"alt": "Sample .env file showing DB_PASSWORD and API_KEY placeholders", "url": "https://cdn.lms.example.com/dotenv-sample.png", "type": "image"}, {"text": "Testing Your Environment", "type": "heading", "level": 2}, {"text": "Before running the full application, write a quick test script to verify that the correct Python interpreter and essential libraries are loaded.", "type": "paragraph"}, {"code": "import sys\nimport numpy as np\nimport pandas as pd\n\nprint(\"Python executable:\", sys.executable)\nprint(\"NumPy version:\", np.__version__)\nprint(\"Pandas version:\", pd.__version__)\nprint(\"Environment ready for production!\")", "type": "code", "language": "python"}, {"text": "Automating Setup with Scripts", "type": "heading", "level": 3}, {"text": "For repeatable deployments, write a shell script that creates the environment, installs dependencies, and runs the validation test. Below is an example for Linux/macOS.", "type": "paragraph"}, {"code": "#!/bin/bash\n# setup_prod_env.sh\nconda env create -f environment.yml\nconda activate prod_env\npython test_environment.py\necho \"Setup complete.\"", "type": "code", "language": "bash"}, {"url": "https://www.youtube.com/embed/dQw4w9WgXcQ", "type": "video", "caption": "Automating Conda Environment Setup for CI/CD"}, {"text": "Troubleshooting Common Issues", "type": "heading", "level": 2}, {"rows": [["`conda command not found`", "Add Anaconda to your PATH during installation, or manually source the conda.sh script."], ["VS Code does not see conda env", "Reload VS Code window, verify the Python extension is installed, and check that the environment was created with a compatible Python version."], ["`Solving environment: failed`", "Update conda (`conda update conda`), clean the cache (`conda clean --all`), or use `mamba` for faster resolution."], ["ImportError after switching environments", "Ensure the VS Code terminal is using the same environment (run `conda activate prod_env` manually)."]], "type": "table", "headers": ["Error", "Solution"]}, {"text": "Always test your environment setup on a clean, isolated machine (e.g., a fresh Docker container or a virtual machine) before deploying to production. This uncovers missing dependencies early.", "type": "callout", "intent": "warning"}, {"text": "Summary and Next Steps", "type": "heading", "level": 3}, {"text": "You now have a repeatable production environment using Anaconda for dependency management and VS Code as your IDE. Next, explore integrating your environment with CI pipelines (GitHub Actions, Jenkins) and containerisation (Docker).", "type": "paragraph"}, {"type": "list", "items": ["Official Conda documentation: https://docs.conda.io/", "VS Code Python tutorial: https://code.visualstudio.com/docs/python", "Best practices for production Python environments (Real Python)"], "style": "unordered"}, {"url": "https://www.youtube.com/embed/dQw4w9WgXcQ", "type": "video", "caption": "Bonus: Advanced VS Code Settings for Conda Environments"}, {"alt": "Workflow infographic: Code → Conda env → VS Code → Test → Deploy", "url": "https://cdn.lms.example.com/prod-env-workflow.png", "type": "image"}, {"url": "https://www.youtube.com/embed/dQw4w9WgXcQ", "type": "video", "caption": "Recap: Full Production Environment Setup"}, {"alt": "Success checkmark with ''Environment Ready'' text", "url": "https://cdn.lms.example.com/success-badge.png", "type": "image"}]', 1, '2e512d6f-0e8f-405c-b3b1-7b92f838bdbf', '2026-05-21 17:47:40.083', '2026-05-21 17:47:40.083'),
	('78a96e12-3b1f-41cf-a677-83a64729a63f', 'Basics', 'basics', '["type: doc","content: [{type: heading","attrs: {level: 1}","content: [{text: hello","type: text}]}","{type: heading","attrs: {level: 2}","content: [{text: hello 1","type: text}]}","{type: paragraph","content: [{text: Hello! You have reached a standard greeting. The word \\"Hello\\" is","type: text}","{text: a common way to say hi","type: text","marks: [{type: bold}]}","{text: , first used a long time ago. Famous songs with this name include the track by","type: text}","{text: Adele","type: text","marks: [{type: link","attrs: {rel: noopener","href: https://en.wikipedia.org/wiki/Hello_(Adele_song)","class: H23r4e","title: null","target: _blank}}","{type: bold}","{type: underline}]}","{text:  and the tune by","type: text}","{text: Lionel Richie","type: text","marks: [{type: link","attrs: {rel: noopener","href: https://www.youtube.com/watch?v=mHONNcZbwDY","class: H23r4e","title: null","target: _blank}}","{type: bold}","{type: underline}]}","{text: . [","type: text}","{text: 1","type: text","marks: [{type: link","attrs: {rel: noopener noreferrer nofollow","href: https://en.wikipedia.org/wiki/Hello_(Adele_song)","class: null","title: null","target: _blank}}]}","{text: ,","type: text}","{text: 2","type: text","marks: [{type: link","attrs: {rel: noopener noreferrer nofollow","href: https://www.youtube.com/watch?v=mHONNcZbwDY","class: null","title: null","target: _blank}}]}","{text: ,","type: text}","{text: 3","type: text","marks: [{type: link","attrs: {rel: noopener noreferrer nofollow","href: https://www.dictionary.com/browse/hello","class: null","title: null","target: _blank}}]}","{text: ,","type: text}","{text: 4","type: text","marks: [{type: link","attrs: {rel: noopener noreferrer nofollow","href: https://learnenglishfluently.com/the-fascinating-history-of-the-word-hello/","class: null","title: null","target: _blank}}]}","{text: ]","type: text}]}","{type: paragraph}","{type: paragraph","content: [{text: Hel