INSERT INTO `Quote` (`id`, `authorName`, `authorRole`, `content`, `imageUrl`, `status`, `featured`, `createdAt`, `updatedAt`, `reviewedAt`, `reviewedBy`) VALUES
	('8c4b07a6-483e-47a4-96cb-7017b8006daf', 'Emmanuel Niyonzima', 'Instructor', 'Every skill we teach here is a seed for someone else''s future.', NULL, 'APPROVED', true, '2026-08-05 15:04:56.908', '2026-08-05 16:32:50.389', '2026-08-05 15:08:51.416', NULL),
	('06acd886-b0f5-44dc-8da1-9907df10c50c', 'Jane Uwase', 'Alumni, Class of 2023', 'Leadership begins with the courage to serve others before yourself.', NULL, 'APPROVED', true, '2026-08-05 15:04:54.831', '2026-08-05 16:32:51.356', '2026-08-05 15:08:46.739', NULL),
	('38a211dc-c37c-450a-b084-d67668656aaf', 'David Habimana', 'Career Advisor', 'Character and competence together are what turn potential into impact.', NULL, 'APPROVED', true, '2026-08-05 15:04:57.378', '2026-08-05 16:32:52.277', '2026-08-05 15:08:53.026', NULL),
	('1647aad4-ca3f-4c02-8e89-aed46c46893a', 'Grace Mukamana', 'Student', 'I came here to learn leadership. I left knowing how to lead myself first.', NULL, 'APPROVED', true, '2026-08-05 15:04:57.145', '2026-08-05 16:32:55.067', '2026-08-05 15:08:49.079', NULL),
	('6dab72b2-9684-4c65-843d-3caf33638ef8', 'Patrick Nkurunziza', 'Instructor', 'The best leaders I know are the best listeners I know.', NULL, 'APPROVED', true, '2026-08-05 15:04:57.851', '2026-08-05 16:32:57.705', '2026-08-05 15:08:56.476', NULL),
	('7ce46908-b447-4f84-baa6-3a3fd075047d', 'Aline Iradukunda', 'Program Coordinator', 'Growth happens in the room where people are honest about their weaknesses.', NULL, 'APPROVED', true, '2026-08-05 15:04:57.614', '2026-08-05 16:32:58.675', '2026-08-05 15:08:50.589', NULL);
INSERT INTO `Review` (`id`, `rating`, `comment`, `courseId`, `createdAt`) VALUES
	('2bad8c41-1668-4b11-873e-3ca21e0b85b1', 5, 'The OODA loop framework completely changed my weekly meetings.', '41e9c0f6-6b32-401a-bdf0-9d404343157c', '2026-04-30 11:55:05.582'),
	('b6c4e3cc-80d7-42c0-a53f-c9aff34c2324', 3, 'A masterclass in strategic thinking for senior leadership.', '41e9c0f6-6b32-401a-bdf0-9d404343157c', '2026-04-30 11:55:05.582'),
	('0e0bd8b1-2936-415b-baf6-30422d05bf55', 2, 'Great insights into cognitive bias, though the case studies are intense.', '41e9c0f6-6b32-401a-bdf0-9d404343157c', '2026-04-30 11:55:05.582'),
	('e81a43b5-4cb9-4653-9477-49a04518dcfe', 3, 'Finally understood how to use game theory in real negotiations.', '41e9c0f6-6b32-401a-bdf0-9d404343157c', '2026-04-30 11:55:05.582'),
	('154c4dad-3d63-46ec-a228-bd7b71862601', 2, 'Practical, data-driven, and perfectly suited for the 2026 market.', '41e9c0f6-6b32-401a-bdf0-9d404343157c', '2026-04-30 11:55:05.582'),
	('640e9b01-cd82-429a-bfbb-83f9f27821a2', 2, 'The psychological safety module was eye-opening for our HR team.', '3167514a-8148-4789-a95b-15ee856f2772', '2026-04-30 11:55:05.582'),
	('92bd696f-4e20-4ad7-8eb9-08e7b4523cdb', 5, 'Great tips on conflict resolution and radical candor.', '3167514a-8148-4789-a95b-15ee856f2772', '2026-04-30 11:55:05.582'),
