INSERT INTO `Scholarship` (`id`, `title`, `description`, `amount`, `type`, `eligibilityCriteria`, `applicationDeadline`, `maxAwards`, `awardsGranted`, `isActive`, `donorId`, `donorName`, `donorLogoUrl`, `createdAt`, `updatedAt`, `slug`) VALUES
	('b2c3d4e5-f6a7-8901-bcde-f12345678901', 'Excellence in Technology Scholarship', 'Awarded to outstanding students demonstrating exceptional academic performance in technology-related fields.', 5000.00, 'MERIT_BASED', '["minGPA: 3.7","yearOfStudy: 2nd year and above","fieldOfStudy: Computer Science or Engineering"]', '2026-06-30 23:59:59', 10, 2, true, 'cmp6w0nuw00018kpdaz43ry4f', 'Ingeri Technologies Ltd', NULL, '2026-01-15 08:00:00', '2026-01-15 08:00:00', 'Excellence-in-Technology-scholarship'),
	('b2c3d4e5-f6a7-8901-bcde-f12345678902', 'Financial Need Support Grant', 'Supporting talented students who face financial barriers to completing their technology education.', 3000.00, 'NEED_BASED', '["fieldOfStudy: Any STEM field","maxFamilyIncome: 30000","enrollmentStatus: Full-time"]', '2026-07-15 23:59:59', 15, 5, true, 'cmp6w0nuw00018kpdaz43ry4f', 'Ingeri Technologies Ltd', NULL, '2026-01-20 09:00:00', '2026-01-20 09:00:00', 'Financial-Need-Support-Grant'),
	('b2c3d4e5-f6a7-8901-bcde-f12345678904', 'Future Innovators General Scholarship', 'Open to all students passionate about technology and innovation regardless of their specific field of study.', 2500.00, 'GENERAL', '["minGPA: 2.8","essayRequired: true","enrollmentStatus: Full-time"]', '2026-09-01 23:59:59', 20, 0, false, 'cmp6w0nuw00018kpdaz43ry4f', 'Ingeri Technologies Ltd', NULL, '2026-02-10 08:30:00', '2026-05-26 20:29:58.429', 'Future-Innovators-General-Scholarship'),
	('b2c3d4e5-f6a7-8901-bcde-f12345678903', 'Women in Tech Leadership Award', 'Empowering women to break barriers and thrive in the technology industry through education and mentorship support.', 4500.00, 'WOMEN_IN_TECH', '["gender: Female","minGPA: 3","fieldOfStudy: Technology or Computer Science","communityInvolvement: true"]', '2026-08-01 23:59:59', 8, 1, true, 'cmp6w0nuw00018kpdaz43ry4f', 'Ingeri Technologies Ltd', NULL, '2026-02-01 10:00:00', '2026-02-01 10:00:00', 'Women-in-Tech-Leadership-Award'),
	('b2c3d4e5-f6a7-8901-bcde-f12345678905', 'Academic Merit Award for Software Engineering', 'Recognizing top-performing students specializing in software engineering and development.', 6000.00, 'MERIT_BASED', '["minGPA: 3.9","yearOfStudy: 3rd year and above","fieldOfStudy: Software Engineering","portfolioRequired: true"]', '2026-07-31 23:59:59', 5, 0, true, 'cmp6w0nuw00018kpdaz43ry4f', 'Ingeri Technologies Ltd', NULL, '2026-03-01 09:00:00', '2026-03-01 09:00:00', 'Academic-Merit-Award-for-Software-Engineering'),
	('f82743b9-3fe1-453c-970f-b25f5beeba8d', 'NextGen Tech Pioneers Scholarship', 'A prestigious funding track sponsored by Apex Global Tech aimed at empowering underrepresented or high-performing students pursuing cutting-edge certifications in Artificial Intelligence and Full-Stack Development at Loyal Academy.', 1500.00, 'MERIT_BASED', '["maxAge: 40","minAge: 20","minGPA: 0","fieldOfStudy: Business, Enterprenurship","educationLevel: high_school","requiredDocuments: [Academic Transcript","Identity Verification","Proof of Enrollment","Essay / Personal Statement","Financial Need Statement","Technical Portfolio / CV","Letter of Recommendation]","customRequirements: [id","card]","additionalRequirements: none"]', '2026-07-31 00:00:00', 10, 0, true, 'cmpk2sjkz0000frpdnrm93uoi', 'Kas', NULL, '2026-05-24 18:07:44.534', '2026-05-24 18:07:44.534', 'nextgen-tech-pioneers-scholarship'),
	('4d8a7324-c9ec-409f-9556-059271e661f7', 'East Africa Future Leaders Grant', 'An equity-focused financial assistance fund designed to support high-potential students facing socioeconomic challenges, ensuring full tuition coverage for engineering and data science modules at Loyal Academy.', 3000.00, 'NEED_BASED', '["maxAge: 34","minAge: 20","minGPA: 0","requiredDocuments: [Academic Transcript","Identity Verification","Technical Portfolio / CV","Letter of Recommendation]","additionalRequirements: none"]', '2026-10-31 00:00:00', 10, 0, true, 'cmpk2sjkz0000frpdnrm93uoi', 'Kas', NULL, '2026-05-24 18:12:21.494', '2026-05-24 18:21:30.867', 'east-africa-future-leaders-grant');
INSERT INTO `ScholarshipApplication` (`id`, `scholarshipId`, `applicantId`, `motivationLetter`, `financialNeedProof`, `status`, `reviewNotes`, `submittedAt`, `reviewedAt`, `reviewedBy`, `additionalDocuments`) VALUES
	('f1bc116d-2a77-4ef8-82d7-75d6edbefa16', 'b2c3d4e5-f6a7-8901-bcde-f12345678901', 'cmon2mo5o0000p4wkye6acmsu', 'No. While Module 5 introduces high-performance model parallel computing on NVIDIA CUDA devices, you do not need to buy hardware. The course provides comprehensive training on configuring, connecting, and running heavy model computations inside free and accessible cloud runtime instances (such as Google Colab and Kaggle workspaces).', 'No. While Module 5 introduces high-performance model parallel computing on NVIDIA CUDA devices, you do not need to buy hardware. The course provides comprehensive training on configuring, connecting, and running heavy model computations inside free and accessible cloud runtime instances (such as Google Colab and Kaggle workspaces).', 'PENDING', NULL, '2026-05-23 13:44:26.255', NULL, NULL, '[]'),
	('e92f0ca2-6f9c-4018-9c48-98b7365123f0', 'b2c3d4e5-f6a7-8901-bcde-f12345678902', 'cmon2mo5o0000p4wkye6acmsu', 'Reasoning: Managing form transitions using local components allows for an incredibly fluid, rapid, and premium UX. You can cleanly parse state mutations before safely passing the consolidated fields to your secure Next.js Server Action in a single network round-trip.', '/uploads/1779547794938-13gyoj.pdf', 'APPROVED', NULL, '2026-05-23 14:50:48.101', '2026-05-26 22:00:26.799', NULL, '[{"url": "/uploads/1779547815218-3pkag1.pdf", "name": "Pisquare.pdf", "type": "TECHNICAL_PORTFOLIO_CV"}, {"url": "/uploads/1779547829553-4f32ca.pdf", "name": "Mobile_Architecture_Report.pdf", "type": "IDENTITY_VERIFICATION"}]'),
	('58815b6c-8eaa-4dff-b736-6e507ea7619d', 'b2c3d4e5-f6a7-8901-bcde-f12345678902', 'cmp0xzsf3000004lb3fod7a3w', 'Build a GitHub/GitLab integration that automatically reviews pull requests using AI. The tool should analyze code for bugs, security vulnerabilities, style violations, and performance issues, then post comments directly on PRs. It must support multiple languages (JavaScript, Python, Java) and provide a configurable rule set. Also includes a dashboard for teams to review AI suggestions and train the model on their codebase.', '/uploads/1779658913545-7hoz8y.pdf', 'APPROVED', NULL, '2026-05-24 21:42:17.092', '2026-05-26 22:00:34.318', NULL, '[]'),
	('dcd76334-9d7a-4a3c-8ad5-f4b6b385e0a5', '4d8a7324-c9ec-409f-9556-059271e661f7', 'cmoxjoytd0000pswk0ddj05p9', 'Build a GitHub/GitLab integration that automatically reviews pull requests using AI. The tool should analyze code for bugs, security vulnerabilities, style violations, and performance issues, then post comments directly on PRs. It must support multiple languages (JavaScript, Python, Java) and provide a configurable rule set. Also includes a dashboard for teams to review AI suggestions and train the model on their codebase.', '/uploads/1779657483755-wqyqxt.pdf', 'APPROVED', NULL, '2026-05-24 21:18:36.723', '2026-05-26 22:03:09.87', NULL, '[]');
